from collections import Counter

def transform(grid):
    counts = Counter(v for row in grid for v in row)
    common = {v for v, _ in counts.most_common(2)}
    background = counts.most_common(1)[0][0]

    rows = [i for i, row in enumerate(grid) if any(v not in common for v in row)]
    cols = [j for j in range(len(grid[0]))
            if any(grid[i][j] not in common for i in range(len(grid)))]

    out = []
    for r1, r2 in zip(rows, rows[1:]):
        line = []
        for c1, c2 in zip(cols, cols[1:]):
            corners = [grid[r1][c1], grid[r1][c2],
                       grid[r2][c1], grid[r2][c2]]
            if corners[0] not in common and all(v == corners[0] for v in corners):
                line.append(corners[0])
            else:
                line.append(background)
        out.append(line)
    return out
